const COLOR_NAME_BY_HEX = {
  '#78C850': 'green',
  '#F08030': 'orange',
  '#78C8F0': 'blue',
  '#A040A0': 'purple',
  '#F8D030': 'yellow',
  '#A8A8A8': 'gray',
  '#A07850': 'brown',
  '#EE99AC': 'pink',
  '#C03028': 'red',
  '#3a3a3a': 'black',
  '#f0f0f0': 'white',
  '#B8B8D0': 'gray',
  '#A8A878': 'gray',
  '#B8A038': 'brown',
  '#705848': 'brown',
  '#705898': 'purple',
  '#E0C068': 'brown',
  '#A8B820': 'green'
};

Object.values(POKEMON_STARTERS).forEach((pokemon) => {
  const normalized = COLOR_NAME_BY_HEX[pokemon.primaryColor] || pokemon.primaryColor;
  pokemon.primaryColor = normalized;
});

function getAllStarters() { return Object.values(POKEMON_STARTERS); }
function getAllPokemon() { return Object.values(POKEMON_STARTERS); }
function getStarterByName(name) { const key = name.toLowerCase().replace(/[^a-z0-9]/g, ""); return POKEMON_STARTERS[key] || null; }
function getStartersByGeneration(gen) { return Object.values(POKEMON_STARTERS).filter(pokemon => pokemon.generation === gen); }
function getStartersByType(type) { return Object.values(POKEMON_STARTERS).filter(pokemon => pokemon.types.includes(type)); }
function getEvolutionLines() {
  const lines = [];
  const seen = new Set();
  Object.values(POKEMON_STARTERS).forEach(pokemon => {
    const lineKey = pokemon.evolutionLine.join("|");
    if (!seen.has(lineKey)) {
      seen.add(lineKey);
      lines.push({ line: pokemon.evolutionLine, type: pokemon.types[0], generation: pokemon.generation });
    }
  });
  return lines;
}
